<script setup>
import { Head, Link, useForm } from '@inertiajs/vue3';
import PortalLayout from '@/Layouts/PortalLayout.vue';
import CustomerNavigation from '@/Components/Customer/CustomerNavigation.vue';
import InputError from '@/Components/InputError.vue';
const props=defineProps({accounts:Array});
const form=useForm({customer_uuid:props.accounts[0]?.uuid||'',amount:'',currency:'NGN',payment_method:'bank_transfer',transaction_reference:'',payment_date:new Date().toISOString().slice(0,10),proof_of_payment:null,notes:''});
const submit=()=>form.post(route('portal.payments.store'),{forceFormData:true});
</script>
<template><Head title="Submit payment"/><PortalLayout area="Customer Portal"><template #navigation><CustomerNavigation active="payments"/></template><div class="mb-6"><h1 class="text-3xl font-bold">Submit payment</h1><p class="mt-2 text-slate-600">Record a payment made outside KernelBridge. Finance will verify the evidence before applying it to an invoice.</p></div><form class="form-card" @submit.prevent="submit"><div class="form-grid"><label>Customer account<select v-model="form.customer_uuid" required><option v-for="account in accounts" :key="account.uuid" :value="account.uuid">{{ account.name }} — {{ account.customer_number }}</option></select><InputError :message="form.errors.customer_uuid"/></label><label>Amount<input v-model="form.amount" type="number" min="0.01" step="0.01" required/><InputError :message="form.errors.amount"/></label><label>Currency<input v-model="form.currency" maxlength="3" class="uppercase" required/><InputError :message="form.errors.currency"/></label><label>Payment method<select v-model="form.payment_method"><option value="bank_transfer">Bank transfer</option><option value="cash">Cash</option><option value="pos">POS</option><option value="card">Card</option><option value="other">Other</option></select></label><label>Transaction reference<input v-model="form.transaction_reference" required/><InputError :message="form.errors.transaction_reference"/></label><label>Payment date<input v-model="form.payment_date" type="date" required/><InputError :message="form.errors.payment_date"/></label><label class="sm:col-span-2">Proof of payment<input type="file" accept=".pdf,.jpg,.jpeg,.png,.webp" required @change="form.proof_of_payment=$event.target.files[0]"/><InputError :message="form.errors.proof_of_payment"/><span class="mt-1 text-xs text-slate-500">PDF or image, maximum 5 MB.</span></label></div><label>Notes<textarea v-model="form.notes" rows="4"/><InputError :message="form.errors.notes"/></label><div class="flex gap-3"><button class="form-button" :disabled="form.processing">Submit for verification</button><Link :href="route('portal.payments.index')" class="rounded-xl border px-6 py-3">Cancel</Link></div></form></PortalLayout></template>
